/**
 * Antigravity PreToolUse hook — protects the generated `.agents/` mirror.
 *
 * `.kiro/` is the source of truth; `.agents/rules|workflows|skills` are generated by
 * `scripts/sync-agent-docs.mjs`. Editing the mirror directly means the work is silently
 * reverted on the next sync, so this hook blocks the write and points at the real file.
 *
 * Wired up in `.agents/hooks.json` under PostToolUse's sibling event PreToolUse, matching
 * the file-writing tools. Reads the tool call from stdin, writes a decision to stdout.
 *
 * `.agents/hooks.json` itself is NOT generated and stays editable.
 */

const MIRROR = /(?:^|[\\/])\.agents[\\/](rules|workflows|skills)[\\/](.+)$/;

/** Maps a path inside the mirror back to its source of truth in `.kiro/`. */
function sourceOfTruth(area, rest) {
  const tail = rest.replaceAll('\\', '/');
  if (area === 'skills') return `.kiro/skills/${tail}`;
  // rules/ and workflows/ both originate from .kiro/steering/
  return `.kiro/steering/${tail.split('/').pop()}`;
}

function readStdin() {
  return new Promise((resolve) => {
    let raw = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => (raw += chunk));
    process.stdin.on('end', () => resolve(raw));
    process.stdin.on('error', () => resolve(''));
  });
}

function respond(decision, reason) {
  process.stdout.write(JSON.stringify(reason ? { decision, reason } : { decision }));
  process.exit(0);
}

const raw = await readStdin();

let payload = {};
try {
  payload = raw ? JSON.parse(raw) : {};
} catch {
  // Unparseable input must never block the agent.
  respond('allow');
}

const args = payload?.toolCall?.args ?? {};
const target = args.TargetFile ?? args.AbsolutePath ?? '';
const match = typeof target === 'string' ? new RegExp(MIRROR).exec(target) : null;

if (!match) respond('allow');

const [, area, rest] = match;
const source = sourceOfTruth(area, rest);

respond(
  'deny',
  [
    `\`.agents/${area}/\` is a generated mirror — editing it here is reverted by the next sync.`,
    `Edit \`${source}\` instead, then run \`npm run sync:agents\`.`,
    'Front matter is per-tool and intentionally not synced; only bodies are mirrored.',
  ].join(' '),
);
